/** Default look, shared by styles.css (React) and the <taglore-whats-new> element. Edit here; styles.css is generated by the build. */
export const CSS = "/* Default look for the What's New dialog and the changelog (React and web components). Override the custom properties or write your own. */\n.taglore-wn, .taglore-cl {\n  --taglore-wn-bg: #fff;\n  --taglore-wn-fg: #111827;\n  --taglore-wn-muted: #6b7280;\n  --taglore-wn-accent: #4f46e5;\n  --taglore-wn-warn: #b45309;\n  --taglore-wn-radius: 14px;\n}\n.taglore-wn {\n  width: min(560px, calc(100vw - 2rem));\n  max-height: min(80vh, 720px);\n  padding: 0;\n  border: 0;\n  border-radius: var(--taglore-wn-radius);\n  background: var(--taglore-wn-bg);\n  color: var(--taglore-wn-fg);\n  box-shadow: 0 24px 64px rgb(0 0 0 / 0.25);\n  font: inherit;\n  overflow: auto;\n}\n.taglore-wn::backdrop { background: rgb(15 23 42 / 0.45); }\n@media (prefers-color-scheme: dark) {\n  .taglore-wn, .taglore-cl { --taglore-wn-bg: #111827; --taglore-wn-fg: #f9fafb; --taglore-wn-muted: #9ca3af; --taglore-wn-accent: #818cf8; --taglore-wn-warn: #fbbf24; }\n}\n.taglore-wn__header { padding: 1.5rem 1.5rem 0.5rem; }\n.taglore-wn__eyebrow { margin: 0 0 0.25rem; font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--taglore-wn-accent); font-weight: 600; }\n.taglore-wn__title { margin: 0 0 0.5rem; font-size: 1.25rem; line-height: 1.3; }\n.taglore-wn__summary { margin: 0; color: var(--taglore-wn-muted); line-height: 1.5; }\n.taglore-wn__body { padding: 0.5rem 1.5rem; }\n.taglore-wn__section-title { margin: 1rem 0 0.5rem; font-size: 0.875rem; }\n.taglore-wn__section--breaking .taglore-wn__section-title { color: var(--taglore-wn-warn); }\n.taglore-wn__list { margin: 0; padding-left: 1.1rem; display: grid; gap: 0.4rem; line-height: 1.45; }\n.taglore-wn__item-desc { color: var(--taglore-wn-muted); }\n.taglore-wn__footer { display: flex; justify-content: flex-end; padding: 1rem 1.5rem 1.5rem; }\n.taglore-wn__close { border: 0; border-radius: 999px; padding: 0.55rem 1.2rem; background: var(--taglore-wn-accent); color: #fff; font: inherit; font-weight: 600; cursor: pointer; }\n.taglore-wn__close:focus-visible { outline: 3px solid color-mix(in srgb, var(--taglore-wn-accent) 40%, transparent); outline-offset: 2px; }\n.taglore-cl { color: var(--taglore-wn-fg); font: inherit; max-width: 760px; }\n.taglore-cl__search { width: 100%; box-sizing: border-box; padding: 0.6rem 0.9rem; margin-bottom: 1.5rem; border: 1px solid color-mix(in srgb, var(--taglore-wn-muted) 40%, transparent); border-radius: 10px; background: var(--taglore-wn-bg); color: inherit; font: inherit; }\n.taglore-cl__search:focus-visible { outline: 3px solid color-mix(in srgb, var(--taglore-wn-accent) 40%, transparent); outline-offset: 1px; }\n.taglore-cl__release { padding: 0 0 1.5rem 1.25rem; margin-left: 0.4rem; border-left: 2px solid color-mix(in srgb, var(--taglore-wn-muted) 30%, transparent); position: relative; }\n.taglore-cl__release::before { content: \"\"; position: absolute; left: -7px; top: 0.35rem; width: 12px; height: 12px; border-radius: 50%; background: var(--taglore-wn-accent); }\n.taglore-cl__release--patch::before { background: var(--taglore-wn-muted); width: 8px; height: 8px; left: -5px; }\n.taglore-cl__meta { margin: 0 0 0.25rem; font-size: 0.8rem; color: var(--taglore-wn-muted); }\n.taglore-cl__version { font-weight: 600; color: var(--taglore-wn-accent); margin-right: 0.5rem; }\n.taglore-cl__title { margin: 0 0 0.35rem; font-size: 1.1rem; line-height: 1.3; }\n.taglore-cl__summary { margin: 0 0 0.5rem; color: var(--taglore-wn-muted); line-height: 1.5; }\n.taglore-cl__empty { color: var(--taglore-wn-muted); }\n";
